export const BODY: string = "\n<p>واٹر مارک بڑھانے میں صرف چند منٹ لگتے ہیں، اور یہ آپ کے کام کی حفاظت کرتا ہے جہاں بھی تصویر جائے۔ آپ کو ڈیزائن سافٹ ویئر یا اکاؤنٹ کی ضرورت نہیں، اور پورا عمل آپ کے براؤزر میں ہوتا ہے۔</p>\n<p>یہ کیسے کریں پورا عمل قدم بہ قدم بتاتا ہے۔ اس میں متن اور لوگو واٹر مارک، جگہ، مبہم پن، سائز، اور ٹائل شدہ نمونہ شامل ہے جو کلائنٹ پروف کی حفاظت کرتا ہے۔</p>\n<p>آخر تک آپ کو معلوم ہو گا کہ واحد تصویر، پروف کا بیچ کیسے نشان زد کریں، اور وہ غلطیاں جو واٹر مارک کو بیکار بناتی ہیں۔ اپنا بغیر نشان والا اصل محفوظ رکھیں جب تک آپ نتیجہ چیک نہ کر لیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: آپ کو کیا چاہیے</h2>\n<p>آپ کو تصویر فائل چاہیے ہوتی ہے اور، اگر آپ لوگو واٹر مارک چاہتے ہیں تو لوگو فائل بھی۔ شفاف PNG لوگو بہترین کام کرتا ہے، کیونکہ اس کے خالی علاقے تصویر کو دکھنے دیتے ہیں۔</p>\n<p>ٹول کھولنے سے پہلے فیصلہ کریں کہ واٹر مارک کو کیا کہنا چاہیے۔ نام، ویب سائٹ، یا مختصر جملہ کافی ہے، اور مختصر متن چھوٹے سائز پر بھی پڑھنا آسان ہوتا ہے۔</p>\n<p>اپنے مقصد کے بارے میں بھی سوچیں۔ پروف کو مضبوط، ہٹانے میں مشکل نشان چاہیے ہوتا ہے، جبکہ سوشل میڈیا کے لیے تیار تصویر کو کونے میں صرف ہلکا برانڈ چاہیے ہوتا ہے۔</p>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-par-watermark-lagayein/\">Image Watermark tool</a> کھولیں۔ سب کچھ مقامی طور پر چلتا ہے، اس لیے آپ کی تصاویر اور آپ کا لوگو کبھی سرور پر اپ لوڈ نہیں ہوتے۔</p>\n<h2 id=\"step-by-step\">چھ قدموں میں واٹر مارک بڑھائیں</h2>\n<p>عمل متن واٹر مارک اور لوگو واٹر مارک کے لیے ایک جیسا ہے۔ تصویر اپ لوڈ کریں، نشان سیٹ کریں، اسے رکھیں، پیش نظارہ چیک کریں، اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>جگہ اور مبہم پن کے ساتھ وقت لیں۔ وہ دو سیٹنگ طے کرتی ہیں کہ واٹر مارک تصویر کی حفاظت کرتا ہے یا صرف اسے سجاتا ہے۔</p>\n<p>شیئر کرنے سے پہلے ڈاؤن لوڈ شدہ فائل کو ایک بار کھولیں۔ تصدیق کریں کہ واٹر مارک صاف پڑھتا ہے اور نیچے تصویر پھر بھی اچھی لگتی ہے۔</p>\n<h2 id=\"choosing-text-or-logo\">متن اور لوگو واٹر مارک کے درمیان چننا</h2>\n<p>متن واٹر مارک تیز ترین آپشن ہے۔ اپنا نام یا اپنی ویب سائٹ لکھیں، اور ٹول اسے سیکنڈوں میں تصویر پر رینڈر کرتا ہے، بغیر اضافی فائلوں کے۔</p>\n<p>لوگو واٹر مارک زیادہ پیشہ ورانہ لگتا ہے، خاص طور پر فوٹوگرافروں اور اسٹوڈیو کے لیے۔ اپنے برانڈ نشان کی شفاف PNG اپ لوڈ کریں، اور یہ تصویر پر ظاہر ہوتا ہے۔</p>\n<p>جب مقصد واضح کاپی رائٹ نوٹس ہو تو متن بہتر ہوتا ہے۔ نام اور سال ملکیت کے بارے میں کوئی شک نہیں چھوڑتے، جبکہ اکیلا لوگو اجنبی سے پہچانا نہیں جا سکتا۔</p>\n<p>آپ دونوں کو ایک ساتھ استعمال کر سکتے ہیں۔ کونے میں چھوٹا لوگو جس کے نیچے آپ کی ویب سائٹ لکھی ہو ایک ہی نشان میں برانڈنگ اور منسوب دونوں دیتا ہے۔</p>\n<h2 id=\"typing-watermark-text\">واٹر مارک متن لکھنا</h2>\n<p>متن مختصر رکھیں۔ نام، اسٹوڈیو نام، یا ویب سائٹ پتہ کافی ہے، اور مختصر متن چھوٹے سائز پر بھی پڑھنے کے قابل رہتا ہے۔</p>\n<p>واٹر مارک میں لمبے جملے نہ لکھیں۔ مکمل کاپی رائٹ نوٹس مصروف تصویر پر پڑھنا مشکل ہوتا ہے، اور یہ تصویر کا اس سے زیادہ حصہ ڈھکتا ہے جتنا اسے چاہیے ہوتا ہے۔</p>\n<p>اپنا اصل نام یا اپنے کاروبار کا نام استعمال کریں، عرفی نام نہیں جسے کوئی پہچانتا نہ ہو۔ واٹر مارک آپ کی شناخت کے لیے ہے، اس لیے اسے بتانا چاہیے کہ آپ کون ہیں۔</p>\n<p>اگر آپ متن ان پٹ خالی چھوڑیں تو ٹول کے پاس متن نشان کے طور پر رینڈر کرنے کے لیے کچھ نہیں ہوتا۔ پہلے متن لکھیں، پھر سائز اور جگہ ایڈجسٹ کریں۔</p>\n<h2 id=\"uploading-a-logo\">اپنا لوگو واٹر مارک کے طور پر اپ لوڈ کرنا</h2>\n<p>شروع کرنے سے پہلے اپنا لوگو شفاف PNG کے طور پر تیار کریں۔ شفافیت تصویر کو خالی علاقوں سے دکھنے دیتی ہے، اس لیے صرف لوگو ہی تصویر پر ظاہر ہوتا ہے۔</p>\n<p>JPG لوگو کا ٹھوس سفید پس منظر ہوتا ہے جو آپ کی تصویر پر مستطیل کے طور پر ظاہر ہوتا ہے۔ یہ غیر پیشہ ورانہ لگتا ہے، اور اسے غلطی کے طور پر دیکھنا آسان ہے۔</p>\n<p>ٹول میں لوگو آپشن سے لوگو اپ لوڈ کریں۔ آپ صفحہ دوبارہ لوڈ کیے بغیر اسے بعد میں بدل سکتے ہیں، جو مفید ہوتا ہے جب آپ مختلف نشان ٹیسٹ کرنا چاہیں۔</p>\n<p>لوگو کو اس سائز پر چیک کریں جس پر آپ اسے استعمال کریں گے۔ پورے سائز پر ٹھیک لگنے والا تفصیلی لوگو چھوٹے واٹر مارک سائز پر دھندلا بن سکتا ہے، اس لیے ضرورت پڑنے پر اسے آسان کریں۔</p>\n<h2 id=\"choosing-placement\">واٹر مارک کہاں جائے یہ چننا</h2>\n<p>اینکر پری سیٹ نشان کو معیاری جگہ پر رکھتے ہیں: کونے، کنارہ، یا بیچ۔ کونے کم سے کم پریشان کرتے ہیں، جبکہ بیچ ہٹانے میں سب سے مشکل ہوتا ہے۔</p>\n<p>جب پری سیٹ فٹ نہ ہوں تو واٹر مارک کو درست اپنی مرضی کی جگہ پر گھسیٹیں۔ آپ نشان کو تصویر کے سادہ علاقے پر رکھ سکتے ہیں، جہاں یہ موضوع ڈھکے بغیر پڑھنے کے قابل ہو۔</p>\n<p>برانڈنگ کے لیے نیچے والا کونہ عام طور پر بہترین ہوتا ہے۔ یہ تصویر کو صاف نشان زد کرتا ہے بغیر موضوع ڈھکے، اور دیکھنے والے لوگو کو وہاں تلاش کرنے کی توقع رکھتے ہیں۔</p>\n<p>حفاظت کے لیے بیچ یا ترچھی جگہ بہتر ہے۔ بیچ میں نشان کو تصویر کو تباہ کیے بغیر کراپ نہیں کیا جا سکتا۔</p>\n<h2 id=\"setting-opacity\">مبہم پن سیٹ کرنا</h2>\n<p>مبہم پن کنٹرول کرتی ہے کہ واٹر مارک کتنا مضبوط لگتا ہے۔ 100 فیصد پر یہ ٹھوس ہوتا ہے اور نیچے تصویر کو بلاک کرتا ہے، جبکہ 10 فیصد پر یہ مدھم بھوت ہوتا ہے جسے نظر انداز کرنا آسان ہے۔</p>\n<p>کلائنٹ پروف کے لیے 30 سے 50 فیصد استعمال کریں۔ نشان صاف پڑھنے کے قابل ہوتا ہے، جو غلط استعمال کو روکتا ہے، مگر کلائنٹ پھر بھی نیچے تصویر کو پرکھ سکتا ہے۔</p>\n<p>تیار تصویر پر برانڈنگ کے لیے 15 سے 25 فیصد عام طور پر کافی ہوتا ہے۔ لوگو تصویر سے توجہ ہٹائے بغیر نظر آتا ہے، اور یہ موضوع سے نہیں لڑتا۔</p>\n<p>مبہم پن کو تصویر کے ہلکے اور تاریک دونوں حصوں پر ٹیسٹ کریں۔ تاریک پس منظر پر صاف نشان روشن آسمان پر غائب ہو سکتا ہے، اور الٹا بھی سچ ہے۔</p>\n<h2 id=\"setting-size\">واٹر مارک سائز سیٹ کرنا</h2>\n<p>واٹر مارک متن تصویر کے فیصد کے طور پر سائز کیا جاتا ہے، مقرر پکسل تعداد کے طور پر نہیں۔ وہی سیٹنگ چھوٹے تھمب نیل اور بڑی کیمرہ تصویر پر مستقل لگتی ہے۔</p>\n<p>بڑی تصویر پر درست لگنے والا سائز چھوٹی پر پوشیدہ ہو سکتا ہے اگر یہ پکسل میں سیٹ ہو۔ فیصد سائزنگ اس مسئلے سے مکمل بچتی ہے۔</p>\n<p>سائز کو ان اصل ابعاد پر چیک کریں جن پر آپ شیئر کریں گے۔ پورے سائز پر معمولی لگنے والا نشان چھوٹے پیش نظارہ پر حاوی ہو سکتا ہے، اور تھمب نیل کے لیے سائز شدہ نشان بڑی تصویر پر غائب ہو سکتا ہے۔</p>\n<p>جب آپ مختلف سائز کی تصاویر کے بیچ کو واٹر مارک کریں تو فیصد سائزنگ نتیجہ کو ان سب میں مستقل رکھتی ہے بغیر آپ کی طرف سے اضافی کام کے۔</p>\n<h2 id=\"setting-rotation\">گھماؤ زاویہ سیٹ کرنا</h2>\n<p>ہلکا زاویہ، عام طور پر 30 سے 45 ڈگری کے قریب، واٹر مارک کو ہٹانا مشکل اور کیپشن سے کم بناتا ہے۔ ترچھا نشان افقی سے زیادہ تصویر کو پار کرتا ہے۔</p>\n<p>پروف کے لیے ترچھا نشان مضبوط انتخاب ہے۔ یہ بیچ اور کناروں سے گزرتا ہے، اس لیے کوئی واحد کراپ اسے صاف نہیں ہٹا سکتا۔</p>\n<p>برانڈنگ کے لیے زاویہ کو صفر پر رکھیں۔ کونے میں سیدھا لوگو پیشہ ورانہ لگتا ہے، جبکہ جھکا ہوا لوگو غلطی کی طرح لگتا ہے جو گزر گئی۔</p>\n<p>زاویہ کو چھوٹے قدموں میں ایڈجسٹ کریں اور پیش نظارہ دیکھیں۔ چند ڈگری جان بوجھ کر لگنے والے نشان اور حادثاتی لگنے والے نشان کے درمیان فرق کر سکتے ہیں۔</p>\n<h2 id=\"tiled-repeat-mode\">ٹائل شدہ دہرائی نمونہ استعمال کرنا</h2>\n<p>کونے میں واحد واٹر مارک ہٹانا آسان ہے، کیونکہ کوئی بھی کونہ کراپ کر سکتا ہے یا ایک چھوٹے نشان پر رنگ کر سکتا ہے۔ ٹائل شدہ نمونہ اس مسئلے کو حل کرتا ہے۔</p>\n<p>ٹائل شدہ موڈ واٹر مارک کو پوری تصویر میں گرڈ میں بار بار رکھتا ہے، اس لیے کوئی کراپ ان سب کو نہیں ہٹا سکتا۔ یہ کلائنٹ پروف کے لیے معیار ہے۔</p>\n<p>جب ٹائل شدہ موڈ آن ہو تو اینکر پری سیٹ چھپ جاتے ہیں، کیونکہ نمونہ ڈیزائن سے پورا فریم گھیرتا ہے۔ آپ اس کے بجائے فاصلہ اور زاویہ کنٹرول کرتے ہیں۔</p>\n<p>ٹائل شدہ نشان کے لیے واحد نشان سے کم مبہم پن استعمال کریں۔ زیادہ مبہم پن پر دہرایا گیا نمونہ تصویر پر حاوی ہوتا ہے، جبکہ ہلکی دہرائی اسے چھپائے بغیر اس کی حفاظت کرتی ہے۔</p>\n<h2 id=\"preview-and-compare\">ڈاؤن لوڈ سے پہلے پیش نظارہ</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ کریں۔ پیش نظارہ بالکل دکھاتا ہے کہ واٹر مارک ایکسپورٹ شدہ فائل پر کیسا لگے گا، بشمول اس کا سائز، مبہم پن، اور جگہ۔</p>\n<p>نشان کو تصویر کے مصروف ترین حصے پر چیک کریں۔ سادہ دیوار پر صاف پڑھنے والا واٹر مارک جنگل، ہجوم، یا نمونے والے کپڑے میں غائب ہو سکتا ہے۔</p>\n<p>اسے روشن ترین اور تاریک ترین علاقوں پر بھی چیک کریں۔ سفید نشان روشن آسمان پر غائب ہو جاتا ہے، اور تاریک نشان سائے میں غائب ہو جاتا ہے، اس لیے دونوں انتہا ٹیسٹ کریں۔</p>\n<p>اگر نشان کہیں اہم ناقابل پڑھ ہو تو اس کا رنگ بدلیں، خاکہ بڑھائیں، یا اسے سادہ علاقے پر منتقل کریں۔ اب اسے ٹھیک کرنا پورا کام دوبارہ کرنے سے تیز ہے۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ چننا</h2>\n<p>شیئر کرنے یا کلائنٹ کو بھیجنے والی تصاویر کے لیے JPG چنیں۔ یہ فائل سائز چھوٹا رکھتا ہے اور ہر جگہ کام کرتا ہے، بشمول پرانے فارم اور میسجنگ ایپس۔</p>\n<p>جب بنیادی تصویر شفاف گرافک یا لوگو ہو تو PNG چنیں۔ PNG شفافیت محفوظ رکھتا ہے، اس لیے دیکھنے والے علاقے ایکسپورٹ میں دیکھنے والے رہتے ہیں۔</p>\n<p>اچھی کوالٹی والی چھوٹی فائلیں چاہیے ہوں تو WebP چنیں۔ یہ ویب تصاویر کے لیے اچھی طرح کام کرتا ہے، اگرچہ چند پرانے سسٹم پھر بھی فارمیٹ مسترد کرتے ہیں۔</p>\n<p>یاد رکھیں کہ کوالٹی سلائیڈر PNG کے لیے چھپتا ہے، کیونکہ PNG لاس لیس ہے اور اس کی کوئی کوالٹی سیٹنگ نہیں جسے ایڈجسٹ کریں۔ یہ معمول رویہ ہے، ٹول کا مسئلہ نہیں۔</p>\n<h2 id=\"watermarking-on-mobile\">فون یا ٹیبلیٹ پر واٹر مارک لگانا</h2>\n<p>ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ اس فون پر تصویر کو واٹر مارک کر سکتے ہیں جس نے اسے لیا۔ اپنی گیلری سے اپ لوڈ کریں، متن لکھیں، اور نشان کو اپنی انگلی سے جگہ پر گھسیٹیں۔</p>\n<p>انگلی سے جگہ دینا ماؤس سے کم درست ہوتا ہے، اس لیے درست کونوں کے لیے اینکر پری سیٹ استعمال کریں۔ وہ نشان کو بغیر کسی گھسیٹ کے کامل رکھتے ہیں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پیش نظارہ کو پورے سائز پر چیک کریں۔ چھوٹی فون اسکرین پر ٹھیک لگنے والا نشان کمپیوٹر پر دیکھنے پر بہت بڑا یا بہت مدھم ہو سکتا ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائلیں آپ کے معمول کے ڈاؤن لوڈ فولڈر میں محفوظ ہوتی ہیں۔ وہاں سے آپ انہیں سیدھا کلائنٹ، ای میل، یا سوشل پوسٹ پر شیئر کر سکتے ہیں۔</p>\n<h2 id=\"troubleshooting\">عام واٹر مارک مسائل کا حل</h2>\n<p>اگر واٹر مارک پوشیدہ ہو تو مبہم پن شاید بہت کم ہے یا رنگ پس منظر سے میل کھاتا ہے۔ مبہم پن بڑھائیں یا رنگ بدلیں اور پیش نظارہ چیک کریں۔</p>\n<p>اگر واٹر مارک موضوع کو ڈھکے تو اسے سادہ علاقے پر منتقل کریں یا اس کا سائز کم کریں۔ چہرہ یا پروڈکٹ چھپانے والا نشان تصویر کے مقصد کو ہراتا ہے۔</p>\n<p>اگر اینکر پری سیٹ غائب ہوں تو چیک کریں کہ ٹائل شدہ موڈ آن ہے یا نہیں۔ پری سیٹ ٹائل شدہ موڈ میں چھپتے ہیں کیونکہ نمونہ پورا فریم گھیرتا ہے، اور وہ بند کرنے پر واپس آتے ہیں۔</p>\n<p>اگر لوگو سفید ڈبہ دکھائے تو لوگو فائل JPG ہے، شفاف PNG نہیں۔ اسے شفاف PNG سے بدلیں اور سفید مستطیل غائب ہو جائے گا۔</p>\n<h2 id=\"quick-tips\">بہتر واٹر مارک کے لیے فوری نکات</h2>\n<p>کاپی کو واٹر مارک کریں، اصل کو کبھی نہیں۔ ایک بار ایکسپورٹ میں فلیٹ شدہ نشان اس فائل سے ہٹایا نہیں جا سکتا، اس لیے اصل ہی آپ کا واحد صاف ورژن ہے۔</p>\n<p>متن مختصر اور لوگو سادہ رکھیں۔ ایک نظر میں پڑھنے میں آسان نشان تفصیلی سے بہتر حفاظت کرتا ہے جو دھندلا بن جاتا ہے۔</p>\n<p>پورے بیچ پر لگانے سے پہلے واٹر مارک کو مصروف تصویر پر ٹیسٹ کریں۔ سادہ پس منظر پر کام کرنے والا نشان پیچیدہ منظر پر ناکام ہو سکتا ہے۔</p>\n<p>اپنی سیٹنگ لکھ کر محفوظ کریں: مبہم پن، سائز، زاویہ، اور جگہ۔ مختصر نوٹ آپ کو ہر تصویر پر وہی نشان دوبارہ بنانے دیتا ہے جو آپ شائع کرتے ہیں۔</p>\n<h2 id=\"watermarking-a-batch\">تصاویر کے بیچ کو واٹر مارک کرنا</h2>\n<p>شادی یا تقریب سیکڑوں تصاویر پیدا کر سکتی ہے جنہیں سب کو ایک ہی نشان چاہیے ہوتا ہے۔ انہیں ایک ایک کر کے واٹر مارک کریں، سیٹنگ کو پورے سیٹ میں ایک جیسی رکھتے ہوئے۔</p>\n<p>شروع کرنے سے پہلے اپنی سیٹنگ لکھیں: متن یا لوگو، مبہم پن، سائز، زاویہ، اور جگہ۔ مختصر نوٹ بیچ کی ہر تصویر کو مستقل رکھتا ہے۔</p>\n<p>بیچ کو ترتیب سے کام کریں اور ہر دسویں تصویر کا پیش نظارہ کریں۔ فوری چیک اس سیٹنگ کو پکڑتا ہے جو درجنوں فائلوں کو متاثر کرنے سے پہلے بھٹک گئی۔</p>\n<p>واٹر مارک شدہ بیچ کو اصل سے الگ فولڈر میں محفوظ کریں۔ proofs-watermarked جیسا صاف فولڈر نام آپ کو نشان زد اور صاف فائلوں کو ملانے سے روکتا ہے۔</p>\n<p>جگہ اور برانڈنگ اصولوں کے لیے <a href=\"/ur/blog/watermark-behtareen-tareeqe/\">Watermark Best Practices: Placement, Opacity and Branding</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-watermark-rehnumai/\">Image Watermark: Complete Guide</a> دیکھیں، اور متن بڑھانے کے لیے <a href=\"/ur/tasveer-par-text-likhein/\">Add Text to Image tool</a> استعمال کریں۔</p>\n<ul>\n<li>اپنی تصویر ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر، یا Ctrl+V سے چسپاں کر کے اپ لوڈ کریں۔</li>\n<li>اپنا واٹر مارک متن لکھیں، یا لوگو آپشن سے اپنا شفاف PNG لوگو اپ لوڈ کریں۔</li>\n<li>اینکر پری سیٹ سے جگہ چنیں، یا واٹر مارک کو درست اپنی مرضی کی جگہ پر گھسیٹیں۔</li>\n<li>مبہم پن، سائز، اور گھماؤ زاویہ سیٹ کریں، اور کلائنٹ پروف کے لیے ٹائل شدہ دہرائی نمونہ آن کریں۔</li>\n<li>نتیجہ کا پیش نظارہ تصویر کے ہلکے اور تاریک حصوں پر کریں تاکہ تصدیق ہو کہ نشان پڑھنے کے قابل رہتا ہے۔</li>\n<li>ایکسپورٹ فارمیٹ اور کوالٹی چنیں، پھر واٹر مارک شدہ تصویر محفوظ کرنے کے لیے Download پر کلک کریں۔</li>\n</ul>\n";

